INSERT INTO `banners` (`id`, `title`, `subtitle`, `image_path`, `link`, `button_text`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Kuncung Bawok', 'Kuncung Bawuk adalah program drama berbahasa Jawa produksi TVRI Yogyakarta yang dikemas dengan nuansa pendidikan dan hiburan. .', 'banners/kHni5NGBoAocazFRnPAeCHlBcVtowuxMuCB03ceO.jpg', 'https://yogyakarta.tvri.go.id/', 'Selengkapnya', 3, 0, '2025-12-08 12:17:35', '2026-07-23 17:05:51'),
(2, 'Pro Justicia', 'Pro Justicia adalah salah satu program unggulan TVRI Yogyakarta yang berbentuk talkshow edukasi hukum yang dikemas secara kreatif , menarik , informatif dan edukatif', 'banners/wfVsqaOO0MyBTraOohL5CO9tmYMgBZki3bwiYmP6.jpg', 'https://yogyakarta.tvri.go.id/', 'Selengkapnya', 3, 0, '2025-12-08 12:19:07', '2026-08-06 10:20:50'),
(4, 'Layanan Satu Data', 'Layanan Satu data TVRI Yogyakarta yang akan memberikan Informasi dan Pelayanan yang cepat akurat dan terintegrasi buat internal dan masyarakat luas', 'banners/SSsnqYBJNyyIY9yVkK1bhiE9CgRPZEJBN1h1bJTQ.jpg', 'https://yogyakarta.tvri.go.id/lasada', 'Selengkapnya', 1, 1, '2026-07-17 11:30:57', '2026-08-06 10:26:07'),
(5, 'Mangayubagya HUT ke-61 TVRI Yogyakarta', 'Ikuti dan saksikan kemeriahan Kegiatan HUT ke-61 TVRI Yogyakarta mulai tanggal 2 - 26  Agustus 2026', 'banners/cnfJTUO8r3YEve2EkuQ9nobSLgvzFOXNkl469rR3.jpg', 'https://drive.google.com/file/d/1e9H9bfyxQaWR1AYte6KRQzNihgGbbF1F/view?usp=sharing', 'Selengkapnya', 0, 0, '2026-07-23 13:16:39', '2026-09-03 01:30:45'),
(6, 'TVRI Yogyakarta', 'Lembaga Penyiaran Publik TVRI', 'banners/rw9o7BXqdPoL1275ljhZ3VbIixqpSn5RgQJiS6iN.jpg', 'https://yogyakarta.tvri.go.id/', 'Selengkapnya', 0, 1, '2026-09-03 01:47:28', '2026-09-03 01:47:28');
INSERT INTO `broadcasts` (`id`, `user_id`, `broadcast_category_id`, `title`, `slug`, `synopsis`, `poster`, `youtube_link`, `status`, `is_active`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Yogyawarta', 'yogyawarta', 'Tentang Yogyawarta\r\nFormat: Berita harian berbahasa Jawa.\r\n\r\nDurasi: ± 30 menit.\r\n\r\nWaktu tayang: Setiap hari pukul 14.00 WIB di TVRI Yogyakarta.\r\n\r\nIsi berita: Informasi aktual seputar DIY, mulai dari pemerintahan, budaya, sosial, hingga fenomena masyarakat.\r\n\r\nTujuan:\r\n\r\nMenyampaikan berita dengan bahasa yang mudah dipahami masyarakat lokal.\r\n\r\nMelestarikan bahasa Jawa dalam dunia penyiaran.\r\n\r\nMemberikan nuansa khas Yogyakarta dalam tayangan televisi publik.', 'broadcast-posters/xdbalYWm4GnwBAeGsxU3ZSOVvPC3sh8l2IPUlHBQ.jpg', 'https://youtu.be/amX1j1AfXLg?si=bxwCOGEYB3P9i2Xm', 'published', 0, '2025-12-08 12:21:00', '2025-12-08 12:21:02', '2026-07-23 17:06:42'),
(2, 1, 2, 'Saba Desa', 'saba-desa', NULL, 'broadcast-posters/kdqnoIWZLkDYD8q9Qsjvd42m8rkiDqAlIiNmn6ic.jpg', NULL, 'published', 1, '2025-12-11 01:08:23', '2025-12-11 01:08:23', '2025-12-11 01:08:23'),
(4, 1, 2, 'Pendopo Kang Tedjo', 'pendopo-kang-tedjo', NULL, 'broadcast-posters/4qQBousIGx8nlesqbZzw0xpcZm1jYxZX38EGTYQt.jpg', NULL, 'published', 1, '2025-12-11 01:09:16', '2025-12-11 01:09:16', '2025-12-11 01:09:16'),
(6, 1, 2, 'Angkringan', 'angkringan', NULL, 'broadcast-posters/WxggrEgxkrQod4Mh9ORrEFmsHQciiSaAdLMNtZbW.jpg', NULL, 'published', 1, '2025-12-11 01:11:26', '2025-12-11 01:11:26', '2025-12-11 01:11:26');
