INSERT INTO `posts` (`id`, `user_id`, `category_id`, `title`, `slug`, `body`, `link_postingan`, `featured_image`, `excerpt`, `status`, `published_at`, `meta_title`, `meta_description`, `views`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Kunjungan Universitas Gajah Mada', 'kunjungan-universitas-gajah-mada', '<div>Pada tanggal <strong>12 Januari 2023</strong>, TVRI Stasiun D.I. Yogyakarta menerima kunjungan dari rombongan <strong>Universitas Gadjah Mada</strong> yang dipimpin oleh <strong>Prof. Dr. Budi Santosa</strong> bersama 15 orang mahasiswa. Kunjungan ini bertujuan untuk melakukan <strong>studi lapangan mengenai penyiaran publik</strong> dan mengenal lebih dekat proses produksi siaran televisi. Rombongan disambut langsung oleh <strong>Kepala Stasiun TVRI Yogyakarta</strong> beserta tim humas, kemudian diajak berkeliling melihat ruang redaksi, studio siaran, serta fasilitas pemancar. Acara ditutup dengan sesi diskusi interaktif mengenai peran TVRI sebagai lembaga penyiaran publik dan dokumentasi berupa <strong>foto bersama di studio utama</strong> sebagai kenang-kenangan.</div>', 'https://www.dummy.comas', 'post-images/xF0Zk5L1m2QYD5X2crsK5PgD6ohSVJJDgawSXr2y.jpg', 'Pada tanggal 12 Januari 2023, TVRI Stasiun D.I. Yogyakarta menerima kunjungan dari rombongan Universitas Gadjah Mada yang dipimpin oleh Prof. Dr. Budi...', 'published', '2025-12-08 12:09:00', NULL, NULL, 688, '2025-12-08 12:11:47', '2026-09-08 12:56:47'),
(2, 7, 3, 'Kemitraan', 'kemitraan Startegis', '<div>&nbsp;Assalamu’alaikum Wr. Wb. Mitra yang budiman, TVRI Stasiun D. I. Yogyakarta saat ini mengudara melalui kanal Digital 29 UHF yang mampu menjangkau seluruh wilayah Daerah Istimewa Yogyakarta dan beberapa kabupaten sekitarnya. Berdasarkan hasil survei kepuasan pemirsa, TVRI Stasiun masih menjadi media televisi lokal yang diminati. Ini membuktikan bahwa TVRI Stasiun D. I. Yogyakarta sangat dekat dengan pemirsanya dan menyajikan berbagai acara unggulan bernuansa lokal. TVRI Stasiun D. I. Yogyakarta senantiasa menawarkan kerjasama dengan melayani para mitra demi tercapainya sinergi yang saling menguntungkan. Terima kasih atas kepercayaannya kepada kami. Wassalamu’alaikum Wr. Wb&nbsp;</div>', 'https://drive.google.com/file/d/1gFvAR04mAPw_Ci9yN6MM2wDQfrjHsAjU/view?usp=sharing', 'post-images/IdDzhQ5i3f3R6VoDjsp9slh5XBAUOFZl90mth71p.jpg', 'Wujudkan Kemitraan Strategis bersama TVRI Yogyakarta untuk Kemajuan bersama', 'published', '2026-07-02 22:29:00', NULL, NULL, 140, '2026-07-02 22:32:46', '2026-09-07 14:31:16'),
(3, 7, 2, 'TVRI Stasiun Yogyakarta Sosialisasi dan Pencanangan Pembangunan  Zona Integritas Menuju (WBK) dan (WBBM)', 'tvri-stasiun-yogyakarta-sosialisasi-dan-pencanangan-pembangunan-zona-integritas-menuju-wbk-dan-wbbm', '<div>Yogyakarta – TVRI Stasiun Yogyakarta meneguhkan komitmennya dalam mewujudkan tata kelola pemerintahan yang bersih, transparan, dan berorientasi pada pelayanan publik melalui kegiatan Sosialisasi dan Pencanangan Zona Integritas Menuju Wilayah Bebas dari Korupsi (WBK) dan Wilayah Birokrasi Bersih dan Melayani (WBBM). Kegiatan tersebut diselenggarakan di Auditorium TVRI Stasiun Yogyakarta pada Jumat (3/7/2026) dan diikuti oleh seluruh pegawai.<br><br>Kepala TVRI Stasiun Yogyakarta, Akhbar Sahidi, dalam sambutan dan arahannya menegaskan bahwa pembangunan Zona Integritas bukan sekadar memenuhi persyaratan administrasi, tetapi merupakan bentuk komitmen bersama dalam membangun budaya kerja yang bebas dari praktik korupsi serta meningkatkan kualitas pelayanan kepada masyarakat.<br><br>Menurut Akhbar, keberhasilan pembangunan Zona Integritas harus diwujudkan melalui implementasi enam area perubahan yang menjadi indikator utama dalam meraih predikat WBK dan WBBM.<br><br>Area pertama adalah manajemen perubahan, yang menekankan pentingnya hadirnya agen-agen perubahan di lingkungan kerja. Kepala Stasiun, Kepala Subbagian Tata Usaha, dan para Ketua Tim Perencanaan dan Pengendalian diharapkan menjadi role model dalam membangun budaya kerja yang berintegritas.<br><br>Selanjutnya, penataan sistem manajemen sumber daya manusia (SDM) dilakukan melalui evaluasi kinerja yang objektif dan adil sehingga setiap pegawai memperoleh penilaian berdasarkan capaian kinerja masing-masing.<br><br>Area berikutnya adalah penguatan akuntabilitas kinerja, yang menuntut setiap unit kerja mampu mempertanggungjawabkan pelaksanaan program secara terukur dan sesuai dengan target yang telah ditetapkan.<br><br>Dalam aspek pengelolaan anggaran, Akhbar menekankan pentingnya penggunaan anggaran secara efektif, efisien, transparan, dan akuntabel agar setiap rupiah yang dibelanjakan memberikan manfaat yang optimal bagi organisasi dan masyarakat.<br><br>Selain itu, penguatan pengawasan menjadi salah satu fokus utama untuk mencegah terjadinya penyimpangan melalui peningkatan pengendalian internal dan pengawasan yang berkesinambungan.<br><br>Sementara itu, pada area peningkatan kualitas pelayanan publik, seluruh pegawai didorong untuk terus meningkatkan kualitas layanan dengan mengedepankan profesionalisme, responsivitas, dan kepuasan masyarakat sebagai penerima layanan.<br><br>Melalui pencanangan Zona Integritas ini, TVRI Stasiun Yogyakarta berharap mampu membangun budaya kerja yang menjunjung tinggi integritas, profesionalisme, dan akuntabilitas di seluruh lini organisasi.<br><br>Lebih dari itu, TVRI Stasiun Yogyakarta menargetkan keberhasilannya dalam membangun Zona Integritas dapat menjadi contoh dan inspirasi bagi stasiun daerah TVRI lainnya dalam mewujudkan Wilayah Bebas dari Korupsi (WBK) dan Wilayah Birokrasi Bersih dan Melayani (WBBM), sehingga tercipta tata kelola lembaga penyiaran publik yang semakin profesional, bersih, dan dipercaya masyarakat.</div>', 'https://drive.google.com/file/d/1ngSimxJVUaBty4cw8GlPxt-R_NMF6WbQ/view?usp=sharing', 'post-images/SIF235B0zJmwPf33F2IOBrwJv5dauO4HB89FnYEl.jpg', 'TVRI Stasiun Yogyakarta meneguhkan komitmennya dalam mewujudkan tata kelola pemerintahan yang bersih, transparan, dan berorientasi pada pelayanan publik melalui kegiatan Sosialisasi dan Pencanangan Zona Integritas Menuju (WBK) dan (WBBM)', 'published', '2026-07-05 19:13:00', NULL, NULL, 132, '2026-07-05 19:17:45', '2026-09-07 13:32:37'),
(4, 7, 2, 'Forum Konsultasi Publik', 'forum-konsultasi-publik', '<div>YOGYAKARTA — TVRI Yogyakarta melaksanakan kegiatan Forum Konsultasi Publik bertema “Transformasi TVRI Yogyakarta Mewujudkan Layanan Berkualitas” pada 21 Mei 2026 di Auditorium TVRI Yogyakarta. Kegiatan ini dihadiri sebanyak 100 undangan dari berbagai kalangan, mulai dari komunitas pemirsa dan pemerhati TVRI, akademisi, budayawan, politisi, rohaniwan, birokrat, stakeholder, organisasi masyarakat, media massa, hingga pengguna layanan kerja sama siaran dan magang. Kehadiran berbagai elemen masyarakat ini menjadi bagian dari upaya TVRI Yogyakarta untuk membangun komunikasi terbuka dengan publik sekaligus menyerap aspirasi secara langsung.<br><br></div><div><br>Kepala TVRI Stasiun Yogyakarta, Akhbar Sahidi, dalam sambutannya menyampaikan bahwa Forum Konsultasi Publik diselenggarakan sebagai bentuk komitmen TVRI Yogyakarta dalam memberikan pelayanan terbaik kepada seluruh stakeholder dan masyarakat.<br><br></div><div><br>“Tujuan diadakan Forum Konsultasi Publik ini adalah untuk melayani stakeholder dan masyarakat secara luas. Melalui kegiatan ini kami berharap dapat meningkatkan pelayanan publik serta menjadi cermin apakah program dan kegiatan di TVRI Yogyakarta sudah sesuai dengan ekspektasi dan harapan masyarakat,” ujarnya.<br><br></div><div><br>Menurut Akhbar, kritik, saran, dan berbagai masukan dari peserta forum akan menjadi bahan evaluasi dalam penyusunan standar pelayanan publik TVRI Yogyakarta. Dengan demikian, layanan yang diberikan dapat semakin relevan dengan kebutuhan masyarakat.<br><br></div><div><br>Melalui Forum Konsultasi Publik ini, TVRI Yogyakarta menegaskan komitmennya untuk terus bertransformasi dalam menghadirkan layanan penyiaran yang berkualitas, profesional, dan berorientasi pada kepentingan publik.</div>', 'https://tvri.go.id/berita/tvri-yogyakarta-gelar-forum-konsultasi-publik-dorong-transformasi-layanan-berkualitas-m52HC4', 'post-images/aTOwBtTVVZaF2WZ6HB7SlRh9bLyQHEGKX7PBVgkC.jpg', 'TVRI Yogyakarta melaksanakan kegiatan Forum Konsultasi Publik bertema “Transformasi TVRI Yogyakarta Mewujudkan Layanan Berkualitas” pada 21 Mei 2026 di Auditorium TVRI Yogyakarta.', 'published', '2026-07-05 19:23:00', NULL, NULL, 149, '2026-07-05 19:25:11', '2026-09-07 23:56:03'),
(5, 9, 1, 'Kunjungan Industri dari Ikatan Mahasiswa Muhammadiyah Universitas Ahmad Dahlan 22 Juli 20026', 'kunjungan-industri-dari-ikatan-mahasiswa-muhammadiyah-universitas-ahmad-dahlan-22-juli-20026', '<div><strong>TVRI Yogyakarta </strong>menerima kunjungan industri dari <strong>Ikatan Mahasiswa Muhammadiyah (IMM) Universitas Ahmad Dahlan</strong> sebagai bagian dari upaya meningkatkan wawasan dan pemahaman mahasiswa mengenai dunia penyiaran.</div><div>Melalui kegiatan ini, peserta memperoleh kesempatan untuk mengenal secara langsung proses produksi program televisi, sistem kerja penyiaran, serta peran TVRI sebagai lembaga penyiaran publik dalam menyampaikan informasi, pendidikan, dan hiburan yang berkualitas kepada masyarakat.</div><div>Terima kasih atas kunjungan yang telah dilakukan. Semoga kegiatan ini memberikan manfaat, memperluas pengetahuan, serta menjadi bekal berharga bagi para mahasiswa dalam mengembangkan kompetensi dan profesionalisme di bidang komunikasi dan penyiaran.</div>', 'https://www.instagram.com/reel/DbFtaT2zlVE/?igsh=MW10cTRyOWFscXAxeg==', 'post-images/SObuMCwD6mvc53yggFFNxj4K87ydqnmfy0Ht311q.jpg', 'TVRI Yogyakarta dengan senang hati menerima kunjungan industri dari Ikatan Mahasiswa Muhammadiyah (IMM) Universitas Ahmad Dahlan.', 'published', '2026-07-22 13:54:00', NULL, NULL, 73, '2026-07-22 13:59:53', '2026-09-07 16:08:21'),
(6, 9, 1, 'Kunjungan Industri dari IAI AN Nawawi Purworejo 22 Juli 2026', 'kunjungan-industri-dari-iai-an-nawawi-purworejo-22-juli-2026-', '<div>&nbsp;<strong>Kunjungan Industri IAI An Nawawi Purworejo di TVRI Yogyakarta<br></strong><br></div><div>TVRI Yogyakarta dengan hangat menyambut kunjungan industri dari <strong>Institut Agama Islam (IAI) An Nawawi Purworejo</strong>. Kegiatan ini menjadi sarana bagi mahasiswa untuk mengenal lebih dekat dunia penyiaran publik, mulai dari proses produksi program, pengelolaan berita, hingga teknologi yang mendukung siaran televisi.</div><div>Melalui kunjungan ini, diharapkan mahasiswa memperoleh wawasan, pengalaman, serta inspirasi mengenai peran media publik dalam menyampaikan informasi yang edukatif, berkualitas, dan berorientasi pada kepentingan masyarakat.</div><div>Terima kasih atas kunjungannya. Semoga silaturahmi ini menjadi awal kolaborasi yang bermanfaat dan memberikan bekal berharga bagi generasi muda dalam menghadapi dunia profesional.</div><div>#TVRIYogyakarta #KunjunganIndustri #IAIAnNawawiPurworejo #MediaPublik #BelajarBersamaTVRI</div>', 'https://www.instagram.com/reel/DbFt832T6sz/?igsh=MTVndWhpNHRkNWkxeg==', 'post-images/HEfvOlpHUiikvwT0QEctwrXgWWQvSbj7YSNrZylm.jpg', 'pada rabu tanggal 22 juli 2026 TVRI Yogyakarta menerima kunjugan industri dari IAI AN Nawawi Purworejo', 'published', '2026-07-22 14:06:00', NULL, NULL, 74, '2026-07-22 14:16:28', '2026-09-08 07:29:57'),
(7, 9, 1, 'Kunjungan Indsutri Dari Man 1 Kulon Progo 21 Juli 2026', 'kunjungan-indsutri-dari-man-1-kulon-progo-21-juli-2026-', '<div>Belajar langsung dari dunia penyiaran! TVRI Yogyakarta dengan senang hati menyambut kunjungan industri dari siswa-siswi <strong>MAN 1 Kulon Progo</strong>. Melalui kegiatan ini, para peserta diajak mengenal lebih dekat proses produksi program televisi, mulai dari tahap perencanaan, produksi, hingga siaran.</div><div>Semoga kunjungan ini menjadi pengalaman yang bermanfaat, menambah wawasan, serta menginspirasi generasi muda untuk terus berkarya dan berinovasi di dunia media dan penyiaran.</div><div>Terima kasih atas kunjungannya. Sampai jumpa di kesempatan berikutnya!&nbsp;</div><div>#TVRIYogyakarta #KunjunganIndustri #MAN1KulonProgo #TVRIMenginspirasi #MediaPenyiaran #BelajarBersamaTVRI</div>', 'https://www.instagram.com/reel/DbC7wauTafR/?igsh=Z3p3anZkM2x4MzNt', 'post-images/1nxDXqofRavIo1pOhV03KkzO7mBO7mN58FFccr21.jpg', 'Pada Selasa 21 Juli 2026 TVRI Yogyakarta menerima kunjungan industri dari MAN 1 Kulon Progo', 'published', '2026-07-23 18:01:00', NULL, NULL, 88, '2026-07-23 18:05:03', '2026-09-08 18:05:16'),
(8, 9, 1, 'TVRI Yogyakarta menerima Kunjungan Industri dari SDN Dukun1 16 Juli 2026', 'tvri-yogyakarta-menerima-kunjungan-industri-dari-sdn-dukun1-16-juli-2026', '<div>Siswa-siswi SD Negri Dukun 1 berkesempatan mengikuti kunjungan industri ke TVRI Yogyakarta untuk menggenal lebih dekat dunia televisi. Mulai dari proses produksi, ruang studio, hingga peran di balik layar, pengalama ini menjadi pembelajaran yang seru sekali menginspirasi. Semoga kunjungan in membuka wawasan menumbuhkan rasa percaya diri,dan memotivasi generasi muda untuk terus bermimpi serta berkarya&nbsp;</div>', 'https://www.instagram.com/reel/Da2GMDkzjtQ/?igsh=bTNpZTFpMXNvbnYw', 'post-images/NvI4ubiL9xQ4rpjf1kct1SayjHipatDNeEnuoxrd.jpg', 'Belajar langsung dari dapur penyiaran', 'published', '2026-07-23 18:08:00', NULL, NULL, 105, '2026-07-23 18:12:42', '2026-09-08 18:22:05'),
(9, 9, 1, 'Kunjugan Industri Dari Universitas Nusa Putra 15 Juli 2025', 'kunjugan-industri-dari-universitas-nusa-putra-15-juli-2025', '<div>Kunjungan industri dari <strong>Universitas Nusa Putra</strong> menjadi kesempatan berharga bagi mahasiswa untuk melihat secara langsung bagaimana proses kerja, inovasi, hingga pengembangan produk dijalankan di dunia industri.</div><div>Melalui kegiatan ini, peserta tidak hanya memperoleh pengalaman baru, tetapi juga memahami bahwa teori di ruang kuliah akan semakin bermakna ketika dipadukan dengan praktik di lapangan. Semoga kunjungan ini menjadi bekal untuk melahirkan generasi yang siap menghadapi tantangan dunia kerja, kreatif dalam berinovasi, serta mampu memberikan kontribusi bagi kemajuan industri di Indonesia.</div><div>Terima kasih atas kunjungan dan antusiasme yang luar biasa. Sampai jumpa di kesempatan berikutnya!</div><div>#KunjunganIndustri #UniversitasNusaPutra #BelajarBersamaIndustri #Kolaborasi #DuniaKerja #Mahasiswa #Inovasi #IndonesiaMaju</div>', 'https://www.instagram.com/reel/DazQACATyg1/?igsh=d2M1NjFwdHZqNm9z', 'post-images/j7eUZo1bUEBUYHq1kNwgzL5BZ4qqStlrjotnlTQM.jpg', 'pada tanggal 15 Juli Tvri Yogyakarta kedatangan kunjungan industri  dari universitas Nusa Putra', 'published', '2026-07-23 18:14:00', NULL, NULL, 90, '2026-07-23 18:20:05', '2026-09-07 21:58:39'),
(10, 9, 1, 'Kunjungan Industri Dari Sekolah SMKN Tanjung Sari', 'kunjungan-industri-dari-sekolah-smkn-tanjung-sari-', '<div>Kunjungan Industri SMKN Tanjungsari ke TVRI Yogyakarta<br><br>Rabu, 29 Juli 2026, TVRI Yogyakarta menerima kunjungan industri dari siswa-siswi SMKN Tanjungsari. Kegiatan ini menjadi sarana bagi para peserta untuk mengenal lebih dekat dunia penyiaran, proses produksi program televisi, serta peran TVRI sebagai lembaga penyiaran publik.<br><br>Selama kunjungan, para siswa mendapatkan pemaparan mengenai alur kerja di TVRI Yogyakarta, mulai dari proses perencanaan program, produksi di studio, hingga penyiaran. Peserta juga berkesempatan melihat secara langsung berbagai fasilitas dan peralatan yang digunakan dalam mendukung kegiatan penyiaran.<br><br>Melalui kegiatan ini, diharapkan para siswa memperoleh wawasan baru mengenai industri penyiaran dan semakin termotivasi untuk mengembangkan kompetensi sesuai dengan bidang keahlian yang mereka tekuni. TVRI Yogyakarta senantiasa terbuka dalam mendukung kegiatan edukatif sebagai upaya mempererat hubungan dengan dunia pendidikan dan mencetak generasi muda yang siap menghadapi dunia kerja.</div>', 'https://www.instagram.com/reel/DbXNe5jTCTU/?igsh=NzV2OWZhbTFya2Ez', 'post-images/hAkOzFKPWjoj98BJyXkjQx53YyUEJFZWLThn1Fx8.jpg', 'TVRI Yogyakarta menerima kunjungan industri dari SMKN Tanjungsari pada Rabu, 29 Juli 2026. Kegiatan ini bertujuan untuk memberikan wawasan kepada para siswa mengenai dunia penyiaran, mulai dari proses produksi hingga penyiaran program televisi.', 'published', '2026-07-30 18:53:00', NULL, NULL, 73, '2026-07-30 18:58:34', '2026-09-07 19:03:31'),
(11, 9, 2, 'Karoke ON TV 31 Juli 2026', 'karoke-on-tv-31-juli-2026-', '<div>Saatnya menunjukkan bakat bernyanyi dan menikmati hiburan yang seru bersama Karaoke On TV!<br><br>Jangan lewatkan keseruan program Karaoke On TV yang hadir hari ini, Jumat, 31 Juli 2026, pukul 14.30–15.30 WIB, hanya di TVRI Yogyakarta. Nikmati lagu-lagu pilihan, bernyanyi bersama, dan rasakan pengalaman karaoke yang menghibur dari rumah maupun melalui partisipasi interaktif.<br><br>Ajak keluarga, sahabat, dan orang terdekat untuk ikut bernyanyi bersama. Saksikan hanya di TVRI Yogyakarta, karena hiburan berkualitas selalu hadir untuk Anda.<br><br>TVRI Yogyakarta, Memang Istimewa.</div>', 'https://www.instagram.com/p/DbXdB6roxHR/?igsh=bG1qOXF0aWlpZzZs', 'post-images/DhqWTfR5CGV35tv7jdkuhzviGfOSznM5WlunraDC.jpg', 'Saatnya bernyanyi, bergembira, dan menikmati penampilan terbaik bersama TVRI Yogyakarta. Jangan lewatkan keseruannya, hanya di Karaoke On TV.', 'published', '2026-07-30 19:05:00', NULL, NULL, 108, '2026-07-30 19:11:36', '2026-09-08 07:29:06'),
(12, 9, 2, 'Rekrtumen Talent Karoke ON TV', 'rekrtumen-talent-karoke-on-tv', '<div><strong>Punya suara merdu dan hobi bernyanyi? Saatnya tampil di layar televisi!</strong><br><br><strong>Karoke ON TV</strong> membuka kesempatan bagi Anda untuk menjadi bagian dari tayangan <strong>TVRI Yogyakarta</strong>. Tunjukkan bakat, percaya diri di depan kamera, dan rasakan pengalaman bernyanyi di panggug televisi. <br><br>jangan lewatkan kesempatan ini! Daftarkan diri anda dan jadilah bintang berikitnya di <strong>Karoke ON TV.&nbsp;</strong></div>', 'https://www.instagram.com/p/Dbm-KF_oJa-/?igsh=MWttMXF0ZzM0dmxxbA==', 'post-images/Tq0q28SjApo3QF42zt0q228KNnNpBXt5w1DDvecg.jpg', 'Karoke ON TV kembali membuka rekrutmen peserta. Bagi anda yan gemar bernyanyi dan ingin tampil di layar TVRI Yogyakarta, inilah saatnya menunjukkan kemampuan terbaik.', 'published', '2026-08-03 17:21:00', NULL, NULL, 92, '2026-08-03 17:36:31', '2026-09-07 15:49:00'),
(13, 9, 1, 'Kunjungan Industri SMK Negeri Nusawungu 04 Agustus 2026', 'kunjungan-industri-smk-negeri-nusawungu-04-agustus-2026', '<div><strong>TVRI Yogyakarta Terima Kunjungan Industri SMK Negri Nusawungu<br><br></strong>TVRI<strong> </strong>Stasiun Yogyakarta menerima kunjungan industri dari siswa dan guru pendamping SMK Negri Nusawungu sebagai bagian dari kegiatan pembelajaran di luar kelas untuk mengenalkan dunia kerja dan industri penyiaran.&nbsp;<br><br>Dalam kegiatan ini, para peserta memperoleh kesempatan utuk mengenal lebih dekat proses produksi program televisi, mulai dari tahapan perencanaan, produksi, hingga penyiaran. Peserta juga diajak mengunjungi&nbsp; sejumlah fasilitas di lingkungan TVRI Yogyakarta serta mendapat pemaparan mengenai peran TVRI sebgai lembaga penyiaran publik yang berkomitmen menghadirkan informasi, pendidikan, hiburan, serta pelestarian budaya.<br><br>Melalui kunjungan ini, diharapkan para sisiwa dapat menambah wawasan, memperluas pengetahuan mengenai dunia penyiaran, serta memperoleh gambaran nyata mengenai kompetensi yan dibutuhkan di industri media. Kegiatan ini juga menjadi bagian dari upaya memperkuat sinergi antara dunia pendidikan dan dunia industri dalam mendukung peningkatan kualitas sumber daya manusia.</div>', 'https://www.instagram.com/reel/Dbpm8r0TgkS/?igsh=amh3dzB6djV0M2Nx', 'post-images/5GMIB56jOcbH7Xu8U88E8TYKXsQOFMFoobKl1hMZ.jpg', 'Selamat datang siswa-siswi SMK Negeri Nusawungu di TVRI Yogyakarta dalam kegiatan kunjungan industri.', 'published', '2026-08-04 17:27:00', NULL, NULL, 106, '2026-08-04 18:10:27', '2026-09-08 07:24:24'),
(14, 9, 2, 'Karoke ON TV 07 Agustus 2026', 'karoke-on-tv-07-agustus-2026', '<div>Saatnya menikmati musik dan hiburan bersama Karoke on TV, program musik pilihan TVRI Yogyakarta yang hadir menemani pemirsa dengan suasana ceria, intreraktif, dan penuh semangat.<br><br>Melalui lantunan lagu dan penampilan para pengisi acara,Karoke on TV menjadi ruang bagi pemirsa untuk menikmati beragam musik sekaligus merasakan keseruan bernyanyi bersama dari rumah. Tak hanya menghibur, program ini juga menjadi wadah untuk memperkenalkan talenta dan karya musik yang dekat dengan masyarakat.<br><br>Jangan lewatkan keseruan Karoke on TV yang tayang hari ini di TVRI Yogyakarta. Siapkan lagu favorit Anda, nikmati suasananya, dan bernyanyilah bersama!</div>', 'https://www.instagram.com/p/DbshxEUI8V2/?igsh=bjdwNzd0cXo0MHFw', 'post-images/uTjB3RZ0mJNr2KaCvI4WJRRbVEA0eMozuj4W2Jhq.jpg', 'Karaoke on TV hadir menemani hari ini dengan musik, hiburan, dan suasana penuh keceriaan. \r\nYuk, nyalakan TV dan ikut bernyanyi bersama Karaoke on TV, hanya di TVRI Yogyakarta!', 'published', '2026-08-06 16:52:00', NULL, NULL, 103, '2026-08-06 17:10:22', '2026-09-07 23:36:39'),
(15, 9, 2, 'SATU FRAME ( TVRI yogyakarta, TVRI jatim, TVRI jateng )', 'satu-frame-tvri-yogyakarta-tvri-jatim-tvri-jateng-', '<div>Indonesia adalah negeri yang kaya akan keberagaman—dari Sabang sampai Merauke. Setiap daerah memiliki cerita, bahasa, adat istiadat, serta kearifan lokal yang tumbuh dan hidup di tengah masyarakatnya. Dalam keberagaman itulah, TVRI hadir sebagai jembatan yang menghubungkan seluruh warna budaya Indonesia dalam satu layar kebersamaan.</div><div>Melalui program dan tayangan lintas stasiun, TVRI menghadirkan <strong>tiga stasiun, tiga budaya</strong>, yang masing-masing membawa identitas dan kekhasan daerahnya. Namun ketika semuanya dipertemukan dalam satu frame, yang tercipta bukanlah perbedaan yang terpisah, melainkan <strong>harmoni yang indah dan saling melengkapi</strong>.</div><div>Setiap tarian daerah, setiap alunan musik tradisional, setiap cerita rakyat, hingga setiap bahasa daerah yang ditampilkan, menjadi pengingat bahwa Indonesia berdiri kokoh karena persatuannya. TVRI tidak hanya menayangkan budaya, tetapi juga merawatnya, mengenalkannya kepada generasi muda, serta menjadikannya kebanggaan bersama.</div>', 'https://www.instagram.com/p/DbshJswogx5/?igsh=YmMxdzF5cWdubDRu', 'post-images/oAaAiNfPHseAMiVaXLI8P80AetDvibjbTzeHvX8U.jpg', 'Sebuah persembahan istimewa yang menghadirkan kolaborasi musik lintas budaya, memper erat persaudaraa, dan merayakan keberagaman indonesia melalui harmoni nada.', 'published', '2026-08-06 17:30:00', NULL, NULL, 112, '2026-08-06 17:44:25', '2026-09-08 10:41:44'),
(16, 9, 2, 'FUN BATTLE BREWING THROWDOWN HUT TVRI KE 61', 'fun-battle-brewing-throwdown-hut-tvri-ke-61-', '<div>Semangat kebersamaan dan kreativitas hadir dalam <strong>Fun Battle Brewing Throwdown</strong> sebagai bagian dari rangkaian peringatan <strong>HUT ke-61 TVRI</strong>.</div><div>Bukan sekadar kompetisi meracik kopi, kegiatan ini menjadi ruang untuk berbagi pengalaman, mengasah kreativitas, sekaligus mempererat kebersamaan di lingkungan TVRI. Adu teknik, cita rasa, dan kreativitas berpadu dalam suasana yang seru dan penuh semangat.</div><div>Melalui kegiatan ini, semangat <strong>HUT ke-61 TVRI</strong> semakin terasa—merayakan perjalanan, memperkuat kebersamaan, dan terus menghadirkan inovasi untuk negeri.</div>', 'https://www.instagram.com/p/Dbr9dVqojs7/?igsh=MWQyOGZ4NzRoOHRlaw==', 'post-images/2V06C1Pt3YQmFyyLl8z3qzryqYWIore1KgKx1v8I.jpg', 'Semarak HUT ke-61 TVRI makin seru dengan hadirnya Fun Battle Brewing Throwdown! \r\nBukan sekadar meracik kopi, tapi tentang kreativitas, sportivitas, dan kebersamaan dalam satu momen.', 'published', '2026-08-06 17:53:00', NULL, NULL, 127, '2026-08-06 18:07:54', '2026-09-08 06:03:08'),
(18, 9, 2, 'Jogja Sehat MERDEKA DARI STUNTING LEWAT GENERASI ANAK ASI', 'jogja-sehat-merdeka-dari-stunting-lewat-generasi-anak-asi-', '<div>JOGJA SEHAT: Merdeka dari Stunting Lewat Generasi Anak ASI<br><br>Dalam rangka memperingati semangat kemerdekaan sekaligus meningkatkan kesadaran masyarakat akan pentingnya kesehatan dan tumbuh kembang anak, TVRI Yogyakarta menghadirkan program JOGJA SEHAT dengan tema:<br><br>“Merdeka dari Stunting Lewat Generasi Anak ASI”<br><br>ASI merupakan salah satu fondasi penting dalam mendukung tumbuh kembang anak sekaligus menjadi bagian dari upaya pencegahan stunting. Melalui dialog informatif dan edukatif, masyarakat diajak untuk memahami lebih jauh pentingnya pemberian ASI serta berbagai langkah yang dapat dilakukan untuk mendukung generasi yang sehat dan bebas stunting</div>', 'https://www.instagram.com/p/Db4rPt4IF4T/?igsh=MTFtMDJoOHVlMGR3eA==', 'post-images/cGTjOozllqSNElRTCrXkEf6cACaHOLX6GW0FxL6H.jpg', 'Jogja Sehat hadir membawa informasi kesehatan yang dekat, edukatif, dan bermanfaat untuk masyarakat Yogyakarta. \r\nYuk, jaga kesehatan mulai dari sekarang', 'published', '2026-08-11 21:28:00', NULL, NULL, 69, '2026-08-11 21:33:33', '2026-09-08 07:31:18'),
(19, 9, 1, 'Kunjungan Industri SMKN 2 Banyumas 12 Agustus 2026', 'kunjungan-industri-smkn-2-banyumas-12-agustus-2026-', '<div>Kunjungan Industri SMKN 2 Banyumas ke TVRI Yogyakarta&nbsp;<br><br>TVRI Yogyakarta menerima kunjungan industri dari SMKN 2 Banyumas pada Rabu, 12 Agustus 2026.<br><br>Kegiatan ini menjadi kesempatan bagi para siswa untuk mengenal lebih dekat dunia penyiaran, mulai dari proses produksi hingga berbagai aktivitas di balik layar yang mendukung hadirnya informasi dan hiburan bagi masyarakat.<br><br>Melalui kunjungan ini, diharapkan para siswa dapat memperoleh wawasan, pengalaman, serta inspirasi mengenai dunia kerja di bidang media dan penyiaran.<br><br>Terima kasih atas kunjungannya, SMKN 2 Banyumas! Semoga pengalaman hari ini dapat menjadi bekal dan motivasi untuk terus berkembang dan berkarya</div>', 'https://www.instagram.com/reel/Db7UFWHz0vc/?igsh=MXBpazB0MW03bTY2', 'post-images/wRw6jN3eQx28IotCf7VL5bHC5IwYYnZ1cXMSEYNH.jpg', 'Belajar langsung mengenal dunia penyiaran, produksi program, hingga proses kerja di balik layar televisi. Semoga menjadi pengalaman dan inspirasi bagi para siswa untuk terus berkarya.', 'published', '2026-08-12 00:03:00', NULL, NULL, 68, '2026-08-12 00:14:42', '2026-09-07 21:00:54'),
(20, 9, 2, 'Jogja Sehat Gema Cermat, Lansia Sehat 13 Agustus 2026', 'jogja-sehat-gema-cermat-lansia-sehat-13-agustus-2026', '<div>Menjaga kesehatan di usia lanjut merupakan bagian penting dalam mewujudkan kualitas hidup yang lebih baik. Melalui program JOGJA SEHAT, TVRI Yogyakarta hadir dengan tema “Gema Cermat, Lansia Sehat” untuk mengajak masyarakat lebih peduli terhadap kesehatan dan kesejahteraan lansia.<br><br>Pada episode kali ini, JOGJA SEHAT menghadirkan dr. Riana Rahmawati, M.Kes., Ph.D sebagai narasumber dan Vira Maya sebagai pembawa acara. Bersama-sama, mereka akan membahas berbagai informasi dan edukasi seputar kesehatan lansia yang penting untuk diketahui oleh masyarakat.</div>', 'https://www.instagram.com/p/Db7R5vMIbDi/?igsh=cGM2Ym5xazkzZ29r', 'post-images/n6fxaoqQscASliMn6L5Jdnef2EuG1NZcfS0l2RiQ.jpg', 'Menjaga kesehatan di usia lanjut adalah investasi untuk tetap aktif, mandiri, dan berkualitas. 💚\r\nLewat Jogja Sehat, simak informasi seputar Gema Cermat Lansia Sehat dan pentingnya meningkatkan pengetahuan serta kepedulian lansia terhadap kesehatan.', 'published', '2026-08-13 18:35:00', NULL, NULL, 68, '2026-08-13 18:41:23', '2026-09-07 20:01:45'),
(21, 9, 1, 'Kunjungan Industri Dari SMKN 12 Surabaya', 'kunjungan-industri-dari-smkn-12-surabaya', '<div>TVRI Yogyakarta menerima kunjungan industri dari SMKN 12 Surabaya sebagai bagian dari upaya memperluas wawsan dan pengalaman peserta didik mengenai dunia penyiaran.<br><br>Dalam kunjungan ini, para siswa berkesempatan mengenal lebih dekat proses kerja di lingkungan TVRI Yogyakarta, mulai dari produksi program, penyiaran, hingga berbagai aktivitas di balik ;ayar. Kegiatan ini menjadi ruang belajar yang inspiratif sekaligus memperkenalkan dunia industri secara langsung kepada generasi muda.<br><br>Semoga kunjungan ini dapat menambah penegtahuan, pengalaman, serta motivasi bagi para siswa untuk terus mengembangkan kreativitas dan kompetensi di bidang yang di minati.</div>', 'https://www.instagram.com/reel/Db-RdE-Tiew/?igsh=YXR4c3N6dmxkMGRi', 'post-images/1haX8wkPwoqEB4DIqvOqfLz6cBRtSWRJZVVkTn9C.jpg', 'TVRI Yogyakarta menerima kunjungan industri dari SMKN 12 Surabaya. Para siswa berkesmpatan mengenal lebih dekat dunia broadcasting, proses produksi program, hingga aktivitas di balik layar', 'published', '2026-08-13 18:48:00', NULL, NULL, 85, '2026-08-13 19:20:15', '2026-09-08 18:22:34'),
(22, 9, 2, 'Karoke ON TV', 'karoke-on-tv-', '<div>Hari ini, <strong>Karoke On TV </strong>kembali hadir menemani pemirsa <strong>TVRI Yogyakarta</strong> dengan sajian musik yang menghibur dan penuh keseruan.<br><br>Nikmati beragam lagu pilhan, lantunkan lagu favorit, dan rasakan serunya bernyanyi bersama dari layar kaca. <strong>Karoke On TV </strong>menjadi ruang bagi siapa saja untuk menikmati musik sekaligus menyalurkan ekspresi dan kecintaan terhadap dunia tarik suara.<br><br>jangan lewatakan keseruannya! Ajak keluarga dan teman untuk menikmati <strong>Karoke On TV</strong> hari ini hanya di<strong> TVRI Yogyakarta.</strong>&nbsp;<br><br>Karena setiap lagu punya cerita, dan setiap suara punya kesempatan untuk didengar.</div>', 'https://www.instagram.com/p/DcALr6_qZHN/?igsh=MWR3bW9pand3bGJtMg==', 'post-images/AyeKzw63CUoofqumPPc9wLFCaEtmFPWs7yKV1Idv.jpg', 'Hari ini, Karoke On TV kembali hadir menemani pemirsa TVRI Yogyakarta Nyanyikan lagu favoritmu, nikmati suasananya, dan temukan keseruan musik yang menemani hari.', 'published', '2026-08-13 20:35:00', NULL, NULL, 70, '2026-08-13 20:55:59', '2026-09-07 15:10:13'),
(23, 9, 2, 'PERGELARAN WAYANG KULIT', 'pergelaran-wayang-kulit-', '<div>&nbsp;<strong>Pagelaran Wayang Kulit dalam Semarak HUT ke-61 TVRI Yogyakarta</strong></div><div>Dalam rangka menyambut <strong>Hari Ulang Tahun ke-61 TVRI Yogyakarta</strong>, mari bersama-sama menikmati kekayaan seni dan budaya Nusantara melalui <strong>Pagelaran Wayang Kulit</strong> yang hadir di layar TVRI Yogyakarta.&nbsp;</div><div>Pagelaran wayang kulit bukan sekadar tontonan, tetapi juga menjadi ruang untuk merawat nilai-nilai budaya, kearifan lokal, serta warisan leluhur agar tetap hidup dan dikenal oleh generasi penerus.</div><div>Melalui semangat <strong>HUT ke-61</strong>, TVRI Yogyakarta terus berkomitmen menghadirkan tayangan yang informatif, edukatif, menghibur, sekaligus turut melestarikan budaya bangsa.</div><div>&nbsp;<strong>Saksikan Pagelaran Wayang Kulit dalam rangka menyambut HUT ke-61 TVRI Yogyakarta.</strong><br>Mari bersama merayakan perjalanan TVRI Yogyakarta sekaligus menjaga budaya tetap lestari dari generasi ke generasi.&nbsp;</div><div>#HUT61TVRIYogyakarta #TVRIYogyakarta #TVRI #PagelaranWayangKulit #WayangKulit #BudayaNusantara #LestarikanBudaya #BudayaJogja #61TahunTVRIYogyakarta</div>', 'https://www.instagram.com/p/Db-E2G0I67c/?igsh=eTkyNW5yOTRmb3d4', 'post-images/kbkvmepRX8i6XET7kYI2kiWKwXQV3yoOV0rvSHvO.jpg', 'Semarak HUT ke-61 TVRI Yogyakarta hadir melalui Pagelaran Wayang Kulit, menyatukan seni, tradisi, dan kearifan budaya Nusantara. \r\n Saksikan kemeriahannya hanya di TVRI Yogyakarta!', 'published', '2026-08-14 00:58:00', NULL, NULL, 93, '2026-08-14 01:03:14', '2026-09-08 18:10:48'),
(24, 9, 2, 'SELAMAT DAN SUKSES ATAS SIDANG TERBUKA PROMOSI DOKTOR ILMU MANAJEMEN UNDIP', 'selamat-dan-sukses-atas-sidang-terbuka-promosi-doktor-ilmu-manajemen-undip', '<div>Segenap keluarga besar <strong>LPP TVRI Stasiun Yogyakarta</strong> mengucapkan <strong>selamat dan sukses kepada Direktur Utama LPP TVRI</strong> atas terselenggaranya <strong>Sidang Terbuka Promosi Doktor Ilmu Manajemen di Universitas Diponegoro (UNDIP)</strong>.</div><div>Pencapaian ini menjadi sebuah kebanggaan sekaligus inspirasi dalam memperkuat kepemimpinan, profesionalisme, dan tata kelola lembaga penyiaran publik.</div><div>Semoga ilmu dan pengalaman yang diperoleh dapat memberikan kontribusi positif bagi kemajuan <strong>LPP TVRI</strong> serta semakin memperkuat peran TVRI sebagai media publik yang informatif, edukatif, menghibur, dan mencerdaskan masyarakat.</div><div><strong>Selamat atas pencapaian yang membanggakan. Terus menginspirasi dan membawa TVRI semakin maju</strong></div>', 'https://www.instagram.com/p/Db9vaVlk7GU/?igsh=bG12NzI2MjEzbnBo', 'post-images/TEWsnsS3OOSc2IcnvmPDZ0JxZTMEOljwrQJS7SIa.jpg', 'Segenap keluarga besar TVRI Yogyakarta mengucapkan selamat kepada Direktur Utama LPP TVRI atas Sidang Terbuka Promosi Doktor Ilmu Manajemen di Universitas Diponegoro (UNDIP).\r\nSemoga pencapaian ini menjadi inspirasi dan membawa semangat baru untuk terus berkarya serta memajukan TVRI', 'published', '2026-08-14 01:04:00', NULL, NULL, 82, '2026-08-14 01:11:24', '2026-09-08 16:53:04'),
(25, 9, 2, 'Agenda Puncak TVRI Yogyakarta Live Concert', 'agenda-puncak-tvri-yogyakarta-live-concert-', '<div><strong>PUNCAK TVRI YOGYAKARTA LIVE CONCERT&nbsp;<br>Bersama Ndarboy Genk 26 Agsutsu 2026 Di Sleman City Hall<br><br></strong>Saatnya bersiap untuk malam penuh musik, energi, dan kemeriahan bersama TVRI Yogyakarta!<br><br>Puncak TVRI Yogyakarta Live Concert akan menghadirkan penampilan spesial Ndarboy Genk pada 26 Agustus 2026. Bersama lantunan lagu-lagu yang akrab di telinga, suasana jogja akan semakin hangat dan meriah dalam satu panggung yang mempertemukan musik, hiburan, dan semangat kebersamaan.<br><br>Bukan sekedar konser momen ini menjadi bagian dari perayaan dan apresiasi TVRI Yogyakarta untuk terus hadir menemani masyarakat melalui karya, informasi, budaya, dan hiburan yang dekat dengan kehidupan masyarakat.&nbsp;<br><br>Siapkan suara terbaikmu, ajak keluarga dan sahabat, dan jangan lewatkan keseruannya!</div>', 'https://www.instagram.com/p/DcDAacPIrmM/?igsh=MWFvcjlmaXpnaTRqNA==', 'post-images/AQzd3oDsG0lUQD46hQbVag0ttejboMpRpRSJz4kQ.jpg', 'Siapkan energi dan nikmati malam penuh musik bersama Ndarboy Genk Dalam Puncak TRVI Yogyakarta Live Concert!\r\nSaatnya bernyanyi bersama, menikmati keseruan, dan merakayakan semangat TVRI Yogyakarta dalam satu panggung! jangan sampai ketinggalan!', 'published', '2026-08-17 23:55:00', NULL, NULL, 94, '2026-08-18 00:23:17', '2026-09-08 02:32:01'),
(26, 9, 2, 'SETETES DARAH SEJUTA HARAPAN', 'setetes-darah-sejuta-harapan', '<div>Kepedulian kepada sesama dapat diwujudkan melalui langkah sederhana yang memiliki arti besar. Dalam semangat berbagi dan membantu masyarakat yang membutuhkan, <strong>TVRI Yogyakarta </strong>akan menggelar kegiatan <strong>Donor Darah</strong> sebagai bagian dari upaya menumbuhkan kepedulian sosial dan semangat kemanusian.<br><br>Kegiatan donor darah ini akan dilaksanakan:<br>📅 <strong>Rabu, 26 Agustus 2026</strong><br>📍 <strong>Sleman City Hall</strong><br><strong>🩸&nbsp; Donor Darah Bersama TVRI Yogyakarta<br><br></strong>Donor darah bukan sekedar memberikan darah yang kita miliki. Lebih dari itu, donor darah merupakan wujud nyata kepedulian yang dapat membantu pasien yang membutuhkan transfusi darah, sekaligus menjadi bentuk solidaritas dan gotong royong di tengah masyarakat.<br><br>Melalui kegiatan ini, <strong>TVRI Yogyakarta</strong>, mengajak seluruh masyarakat untuk turut mengambil bagian dalam aksi kemanusian. Karena satu kantong darah yang kita donorkan dapat menjadi harapan bagi seorang yang sedang berjuang untuk pulih.<br><br>mari bersama-sama hadir, berbagi, dan menerbarkan kebaikan. Tidak perlu menuggu untuk melakukan hal besar, <strong>karena kebaikan kecil yang dilakukan bersama dapat memberikan dampak yang besar bagi sesama.</strong></div>', 'https://www.instagram.com/p/DcBDXsWoosJ/?igsh=MWlveXV3eG5hMnFndQ==', 'post-images/XsqU3FbOmr9VhMhbAUADYrfmcLqxBvWwPp6kqWb8.jpg', 'YUK DONOR DARAH!\r\nJadikan 26 Agustus sebagai momentum untuk berbagi kehidupan dan menghadirkan harapan bagi mereka yang membutuhkan.', 'published', '2026-08-18 23:45:00', NULL, NULL, 71, '2026-08-19 00:07:06', '2026-09-08 12:08:37'),
(27, 9, 2, 'RANAH PUBLIK JUM\'AT 21 AGUSTUS 2026', 'ranah-publik-jumat-21-agustus-2026-', '<div><strong>Ranah Publik: Refleksi usia 61 tahun, TVRI Yogyakarta </strong>terus meneguhkan perjalanan panjangnya sebagai lembaga penyiaran publik yang hadir di tengah masyarakat. Berbagai karya, informasi, edukasi serta program yang mengangkat potensi dan budaya daerah menjadi bagian dari perjalanan TVRI Yogyakarta dalam memberikan kontribusi bagi masyarakat. <br><br>Melalui program <strong>Ranah Publik</strong> yang tayang hari ini, TVRI Yogyakarta menghadirkan tema <strong>\"Refleksi 61 Tahun TVRI Yogyakarta\"</strong>.Tema ini menjadi momentum untuk melihat kembali perjalanan, dinamika, serta berbagai capaian yang telah dilalui selama lebih dari enam dekade dalam dunia penyiaran.<br><br>Refleksi 61 tahun bukan sekedar mengenang perjalanan masa lalu, tetapi juga menjadi kesempatan untuk mengevaluasi dan memperkuat langkah ke depan. Di tengah perkembangan teknologi dan perubahan pola konsumsi infromasi masyarakat, <strong>TVRI Yogyakarta</strong> terus berupaya beradaptasi dengan menghadirkan konten yang relevan, berkualitas, dan tetap berlandaskan nilai-nilai budaya serta kepentingan publik.<br><br>Selama 61 tahun, TVRI Yogyakarta juga menjadi bagian dari denyut kehidupan masyarakat Yogyakarta, menghadirkan beragam informasi mengenai sosial, budaya, pendidikan, ekonomi, hingga berbagai potensi daerah. Komitmen untuk menjaga kekayaan budaya Yogyakarta sekaligus membuka ruang bagi kreativitas masyarakat menjadi bagian penting dalam perjalanan tersebut.<br><br>Melalui <strong>Ranah Publik</strong>, pemirsa diajak untuk bersama-sama merefleksikan perjalanan <strong>61 Tahun TVRI Yogyakarta</strong>, sekaligus melihat harapan dan semangat untuk terus tumbuh menjadi televisi publik yang semakin dekat, dipercaya, dan memberikan manfaat bagi masyarakat.<br><br><strong>61 Tahun TVRI Yogyakarta - terus melangkah, terus berkarya, dan terus hadir untuk masyarakat.</strong><br><br><br></div>', 'https://www.instagram.com/p/DcQN3LdI59m/?igsi=aGZ0NHFmMzhqbG53', 'post-images/oqYY2mE2hss6x7OPAEb7MEJrcV80dEhgEDoCCEVd.jpg', 'Enam dekade lebih menjadi bagian dari perjalanan masyarakat Yogyakarta, TVRI Yogyakarta terus tumbuh, beradaptasi, dan menghadirkan karya yang mengedepankan informasi, edukasi, serta pelestarian budaya.', 'published', '2026-08-20 20:30:00', NULL, NULL, 59, '2026-08-20 21:09:19', '2026-09-08 16:49:32'),
(28, 9, 2, 'KAROKE ON TV JUM\'AT 21 AGUSTUS 2026 LIVE', 'karoke-on-tv-jumat-21-agustus-2026-live-', '<h1>Karaoke on TV Hadirkan Graviti Pulse, Temani Sore Pemirsa TVRI Yogyakarta</h1><div><strong>Yogyakarta –</strong> Sore hari semakin meriah bersama <strong>Karaoke on TV</strong> yang kembali hadir menemani pemirsa TVRI Yogyakarta dengan sajian musik dan hiburan yang menarik. Pada episode kali ini, <strong>Graviti Pulse</strong> akan hadir sebagai bintang tamu dengan penampilan musik yang siap menghibur dan mengajak pemirsa menikmati suasana sore dengan penuh keceriaan.</div><div>Kehadiran Graviti Pulse menjadi salah satu sajian spesial yang sayang untuk dilewatkan. Melalui penampilan musik yang energik dan menghibur, Graviti Pulse siap memberikan warna tersendiri dalam episode <strong>Karaoke on TV</strong> kali ini.</div><div>Karaoke on TV menjadi ruang bagi para musisi dan talenta untuk berbagi karya sekaligus menghadirkan hiburan yang dekat dengan masyarakat. Tidak hanya menyuguhkan lagu-lagu pilihan, program ini juga menghadirkan suasana santai dan hangat sehingga pemirsa dapat menikmati musik dari rumah.</div><div>Bagi para pencinta musik dan pemirsa setia TVRI Yogyakarta, jangan lewatkan penampilan <strong>Graviti Pulse</strong> dalam <strong>Karaoke on TV</strong>.</div><div>🎤 <strong>Karaoke on TV</strong><br>🎶 <strong>Featuring: Graviti Pulse</strong><br>📅 <strong>Tayang hari ini</strong><br>⏰ <strong>Pukul 14.30 WIB</strong><br>📺 <strong>Hanya di TVRI Yogyakarta</strong></div><div>Mari habiskan waktu sore dengan alunan musik dan hiburan bersama <strong>Karaoke on TV</strong>. Saksikan penampilan <strong>Graviti Pulse</strong> dan nikmati keseruannya hanya di <strong>TVRI Yogyakarta</strong>.</div><div><strong>Karaoke on TV – Musiknya dekat, hiburannya melekat!</strong></div><div><br></div>', 'https://www.instagram.com/p/DcSMQzAoYJm/?igsi=MWcxeWR2ZXo5cmpheA==', 'post-images/SxDYNVByJUOTxJ9cISbSmTpu1dl4KupUe4pdEVcd.jpg', 'Yogyakarta - Program Karaoke on TV (KOT) Live Show kembali hadir untuk menemani pemirsa dalam sajian musik dan hiburan. Mengusung tema Kingdom of Talent, program ini menghadirkan penampilan spesial dari Gravity Pulse pada Jumat, 21 Agustus 2026.', 'published', '2026-08-21 01:24:00', NULL, NULL, 67, '2026-08-21 01:31:21', '2026-09-08 18:09:29'),
(29, 9, 2, 'PENGUMUMAN PENTING KEPADA PEMIRSA TVRI YOGYAKARTA YANG KAMI HORMATI', 'pengumuman-penting-kepada-pemirsa-tvri-yogyakarta-yang-kami-hormati', '<div>PENGUMAMAN PENTING UNTUK PEMIRSA TVRI YOGYAKARTA <br><br><strong>Tvri Yogyakarta </strong>menyampaikan infromasi penting kepada seluruh pemirsa terkait rencana penerapan <strong>Electronic Program Guide (EPG)</strong> pada layanan siaran digital LPP TVRI Stasiun Yogyakarta.<br><br>EPG merupakan layanan panduan program siaran yang membantu pemirsa memperoleh informasi mengenai jadwal dan program televisi yang sedang maupun akan ditayangkan. Sehubung dengan penerapan tersebut, pada saat siaran TVRI Yogyakarta belum dapat ditrima dengan baik atau tidak muncul pada perangkat televisi digital, pemirsa diimbau untuk <strong>melakukan scan ulang (pencarian ulang) saluran TV digital </strong>pada prangkat masing-masing.<br><br>Langkah sederhana ini diperlukan agar perangkat televisi dapat kembali menemukan dan menyimpan layanan siaran TVRI Yogyakarta setelah adanya penyesuaian layanan.<br><br><strong>Mohon simak Informasi pada gambar dan lakukan scan ulang apabila diperlukan</strong><br><br>Terima Kasih atas perhatian, pengertian, dan dukungan seluruh pemirsa setia <strong>TVRI Yogyakarta. </strong>&nbsp;</div>', 'https://www.instagram.com/p/DchsMFAoAnb/?igsi=MXVzaDZpanV4enR3OQ==', 'post-images/4Q1BReCGg8eDjzuVVRI8IpsKMSWMTlvAA1PhWNCh.jpg', 'Pengumuman Penting Untuk Pemirsa TVRI Yogyakarta', 'published', '2026-08-26 23:31:00', NULL, NULL, 43, '2026-08-27 00:36:06', '2026-09-07 19:54:58'),
(30, 9, 2, 'KAROKE ON TV JUM\'AT 28 AGUSTUS 2026', 'karoke-on-tv-jumat-28-agustus-2026-', '<div>🎤 KARAOKE ON TV – KOT LIVE SHOW 🎶</div><div><strong>“Kingdom of Talents”</strong></div><div>Siapkan diri untuk menikmati keseruan dan warna-warni talenta dalam <strong>Karaoke on TV – KOT Live Show</strong>! ✨🎶</div><div>Kali ini, <strong>KOT Live Show</strong> hadir dengan penampilan spesial dari <strong>Dindy</strong>, ditemani host <strong>Zhafira &amp; Cindy</strong> yang siap membawa suasana semakin meriah. Nikmati sajian musik, hiburan, dan aksi talenta dalam program yang menghadirkan ruang bagi siapa saja untuk berekspresi dan menunjukkan kemampuan terbaiknya.</div><div>📅 <strong>Jumat, 28 Agustus 2026</strong><br>⏰ <strong>Pukul 14.30–15.30 WIB</strong><br>📺 <strong>Live di TVRI Yogyakarta</strong></div><div>Jangan lewatkan keseruannya! Saksikan <strong>Karaoke on TV – KOT Live Show</strong>, <em>Kingdom of Talents</em>, hanya di <strong>TVRI Yogyakarta</strong>. 🎤✨</div><div><strong>TVRI Yogyakarta — Bersama Menghibur, Menginspirasi, dan Memberi Ruang bagi Talenta Negeri.</strong></div><div>#KaraokeOnTV #KOTLiveShow #KingdomOfTalents #TVRIYogyakarta #TVRI #Dindy #Zhafira #Cindy #LiveShow #TalentaIndonesia #HiburanJogja</div>', 'https://www.instagram.com/p/DckOtA6I8RZ/?igsi=MTYzcHRpeHd2ZDBjMA==', 'post-images/ndYvD9k6XIdnvIcduAEgDk6IojRhjhQeYjNITlyZ.jpg', 'Saatnya seru-seruan bareng KOT Live Show! \r\nJangan lewatkan penampilan spesial DINDY yang siap menghibur dengan sajian musik penuh warna.', 'published', '2026-08-28 01:27:00', NULL, NULL, 35, '2026-08-28 01:31:20', '2026-09-07 20:27:28'),
(31, 9, 2, 'RANAH PUBLIK JUM\'AT 28 AGUSUTSU 2026', 'ranah-publik-jumat-28-agusutsu-2026-', '<div>RANAH PUBLIK TVRI YOGYAKARTA</div><div>&nbsp;<strong>Bongkar Rahasia Mudahnya Umroh Haji dan Percepatan Rezeki Bersama Arminareka</strong>&nbsp;</div><div>Ingin mengetahui lebih jauh tentang kemudahan dalam mewujudkan impian beribadah ke Tanah Suci sekaligus membuka peluang mempercepat rezeki? Simak pembahasannya dalam <strong>Ranah Publik</strong> TVRI Yogyakarta.</div><div>Pada episode kali ini, <strong>Heny Ratifawati</strong>, KORPS Wanita TNI Angkatan Laut, Trainer &amp; Motivator Umroh, serta Tour Leader Bersertifikasi BNSP, bersama <strong>Yani ST.rKeb.Bdn</strong>, Owner Klinik Kusuma Husada sekaligus Manajer Arminareka Perdana, akan berbagi informasi dan pengalaman seputar perjalanan umroh, haji, serta peluang bersama Arminareka.</div><div>Dipandu oleh <strong>Moch Hafidz</strong>, Ranah Publik hadir untuk mengupas informasi secara lebih dekat, terbuka, dan inspiratif bagi masyarakat.</div><div>📅 <strong>Jumat, 28 Agustus 2026</strong><br>⏰ <strong>Pukul 17.00 WIB</strong><br>📺 <strong>LIVE di TVRI Yogyakarta</strong><br>▶️ Streaming melalui <strong>KLIK TVRI</strong></div><div>Jangan lewatkan <strong>Ranah Publik</strong> dan temukan informasi inspiratif yang mungkin menjadi langkah awal menuju impian Anda ke Tanah Suci.&nbsp;</div><div>#RanahPublik #TVRIYogyakarta #TVRI #Umroh #Haji #Arminareka #PercepatanRezeki #Inspirasi #KLIKTVRI #TVRIMediaPemersatuBangsa</div>', NULL, 'post-images/rdzfk1udrpKu259su8pPRewKfJj7xMr2cgLKG9en.jpg', 'Punya impian menunaikan ibadah umroh dan haji? \r\nYuk, simak pembahasan menarik “Bongkar Rahasia Mudahnya Umroh Haji dan Percepatan Rezeki Bersama Arminareka” dalam Ranah Publik!', 'published', '2026-08-28 01:31:00', NULL, NULL, 46, '2026-08-28 01:36:36', '2026-09-08 17:30:54'),
(32, 9, 1, 'Kunjungan Industri Dari SMK Muhammadiyah 2 Nganjuk', 'kunjungan-industri-dari-smk-muhammadiyah-2-nganjuk-', '<div>KUNJUNGAN INDUSTRI SMK MUHAMMADIYAH 2 NGANJUK KE TVRI YOGYAKARTA</div><div>TVRI Yogyakarta kembali menerima kunjungan industri dari <strong>SMK Muhammadiyah 2 Nganjuk</strong> sebagai bagian dari upaya memperluas wawasan dan pengalaman peserta didik mengenai dunia kerja, khususnya di bidang penyiaran dan media.</div><div>Dalam kunjungan ini, para siswa berkesempatan mengenal lebih dekat berbagai proses kerja di lingkungan TVRI Yogyakarta, mulai dari produksi program, penyiaran, hingga aktivitas di balik layar yang mendukung terselenggaranya sebuah tayangan televisi. Kegiatan ini menjadi kesempatan bagi para peserta didik untuk melihat secara langsung bagaimana teori dan pembelajaran yang diperoleh di sekolah diterapkan dalam dunia industri.</div><div>Melalui kunjungan industri, diharapkan para siswa dapat memperoleh pengalaman baru, menambah pengetahuan, serta semakin termotivasi untuk mengembangkan keterampilan dan potensi diri sesuai dengan bidang yang diminati.</div><div>TVRI Yogyakarta mengapresiasi kehadiran <strong>SMK Muhammadiyah 2 Nganjuk</strong> dan berharap kegiatan ini dapat menjadi pengalaman yang bermanfaat serta membuka wawasan generasi muda tentang dunia penyiaran dan industri kreatif.</div><div><strong>Belajar langsung dari dunia industri, membuka wawasan, mengembangkan potensi, dan mempersiapkan generasi muda menuju dunia kerja.</strong></div><div>#TVRIYogyakarta #KunjunganIndustri #SMKMuhammadiyah2Nganjuk #DuniaIndustri #Penyiaran #Media #Pendidikan #GenerasiMuda #TVRIMediaPemersatuBangsa</div>', 'https://www.instagram.com/reel/DciTg5pzrhM/?igsi=MXA2dTI3eXgzamlt', 'post-images/3GlXPWSAiO7frvkkg9dpXwPmnzhjAinwMRQ0mEUa.jpg', 'TVRI Yogyakarta menerima kunjungan industri dari SMK Muhammadiyah 2 Nganjuk!\r\nTerima kasih SMK Muhammadiyah 2 Nganjuk atas kunjungannya. Semoga menjadi pengalaman yang inspiratif dan membawa semangat baru untuk terus belajar, berkarya, dan mengembangkan potensi!', 'published', '2026-08-28 01:39:00', NULL, NULL, 50, '2026-08-28 01:45:39', '2026-09-08 17:30:57');
INSERT INTO `posts` (`id`, `user_id`, `category_id`, `title`, `slug`, `body`, `link_postingan`, `featured_image`, `excerpt`, `status`, `published_at`, `meta_title`, `meta_description`, `views`, `created_at`, `updated_at`) VALUES
(33, 9, 1, 'Kunjungan Industri Dari SMK NU Ungaran', 'kunjungan-industri-dari-smk-nu-ungaran-', '<div>KUNJUNGAN INDUSTRI SMK NU UNGARAN KE TVRI YOGYAKARTA</div><div>TVRI Yogyakarta kembali menerima kunjungan industri dari <strong>SMK NU Ungaran</strong> sebagai bagian dari kegiatan pembelajaran di luar lingkungan sekolah. Kunjungan ini menjadi kesempatan bagi para siswa untuk mengenal lebih dekat dunia kerja, khususnya di bidang <strong>penyiaran, produksi program televisi, dan industri media</strong>.</div><div>Dalam kegiatan tersebut, para siswa mendapatkan wawasan mengenai berbagai aktivitas di lingkungan TVRI Yogyakarta serta proses kerja yang berlangsung di balik sebuah tayangan televisi. Pengalaman ini diharapkan dapat menambah pengetahuan dan memberikan gambaran nyata kepada siswa mengenai dunia industri yang sesuai dengan perkembangan teknologi dan kebutuhan dunia kerja saat ini.</div><div>Melalui kunjungan industri, siswa tidak hanya memperoleh pengetahuan secara langsung, tetapi juga didorong untuk mengembangkan kreativitas, keterampilan, komunikasi, serta kesiapan menghadapi dunia profesional.</div><div>TVRI Yogyakarta mengucapkan terima kasih kepada <strong>SMK NU Ungaran</strong> atas kunjungannya. Semoga kegiatan ini menjadi pengalaman yang berkesan, inspiratif, dan memberikan manfaat bagi para siswa dalam mempersiapkan masa depan.</div><div><strong>Belajar langsung dari industri, memperluas wawasan, dan menumbuhkan semangat untuk terus berkarya.</strong> 🎥📺✨</div><div>#TVRIYogyakarta #KunjunganIndustri #SMKNUUngaran #DuniaPenyiaran #IndustriMedia #Pendidikan #GenerasiMuda #BelajarBerkarya #TVRIMediaPemersatuBangsa</div>', 'https://www.instagram.com/reel/Dck-s86z6S5/?igsi=d3NsZ2IzZmlpaTBz', 'post-images/BzpoFYo69PZ80tnRwH5LoKvXO5Ye5JEMj5VFGAco.jpg', 'TVRI Yogyakarta kembali menerima kunjungan industri dari SMK NU Ungaran!\r\nTerima kasih SMK NU Ungaran atas kunjungannya. Semoga pengalaman ini menjadi bekal untuk terus belajar, berkreasi, dan mempersiapkan diri menuju dunia kerja!', 'published', '2026-08-28 02:01:00', NULL, NULL, 70, '2026-08-28 02:08:09', '2026-09-08 01:37:16'),
(34, 9, 3, 'Kunjungan Kerja Ketua Dewan Pengawas LPP TVRI Ke TVRI Stasiun Yogyakarta', 'kunjungan-kerja-ketua-dewan-pengawas-lpp-tvri-ke-tvri-stasiun-yogyakarta-', '<div>📍 KUNJUNGAN KERJA DEWAN PENGAWAS LPP TVRI KE TVRI YOGYAKARTA</div><div>TVRI Yogyakarta menerima <strong>kunjungan kerja Dewan Pengawas LPP TVRI</strong> sebagai bagian dari upaya memperkuat koordinasi, evaluasi, serta sinergi dalam pelaksanaan tugas dan fungsi penyiaran publik.</div><div>Kunjungan ini menjadi momentum untuk berdiskusi dan bertukar gagasan mengenai berbagai perkembangan, tantangan, serta strategi penguatan TVRI sebagai lembaga penyiaran publik yang senantiasa hadir memberikan informasi, edukasi, dan hiburan berkualitas bagi masyarakat.</div><div>Melalui kunjungan kerja ini, diharapkan terjalin komunikasi dan koordinasi yang semakin baik dalam mendukung peningkatan kinerja serta penguatan peran <strong>TVRI Yogyakarta</strong> sebagai media pemersatu bangsa dan sumber informasi yang terpercaya.</div><div>🤝 <strong>Bersinergi, berkolaborasi, dan terus berkomitmen menghadirkan layanan penyiaran publik terbaik untuk masyarakat.</strong></div><div>#TVRIYogyakarta #TVRI #DewanPengawasLPP TVRI #KunjunganKerja #PenyiaranPublik #Sinergi #Kolaborasi #MediaPemersatuBangsa</div>', 'https://www.instagram.com/p/Dck8mhUTqlv/?igsi=b3IxbDRpcDZkNmU4', 'post-images/AYPprKEIKX6FolgHfIoGXKjf4dZXnFOLFoL3Kvj9.jpg', 'TVRI Yogyakarta menerima kunjungan kerja Dewan Pengawas LPP TVRI sebagai momentum untuk memperkuat koordinasi, sinergi, dan kolaborasi dalam mendukung pelaksanaan tugas serta fungsi TVRI sebagai lembaga penyiaran publik.', 'published', '2026-08-28 02:11:00', NULL, NULL, 75, '2026-08-28 02:18:32', '2026-09-08 19:50:15'),
(35, 9, 2, 'GERAKAN PANGAN MURAH', 'gerakan-pangan-murah-', '<div><strong>GERAKAN PANGAN MURAH HADIR DI TVRI YOGYAKARTA</strong> <br><br>Dalam upaya mendukung keterjangkauan harga kebutuhan pokok sekaligus membantu masyarakat memenuhi kebutuhan pangan,<strong> TVRI Yogyakarta akan menyelenggarakan Gerakan Pangan Murah.<br></strong><br>Kegiatan ini menjadi bagian dari langkah bersama dalam menghadirkan akses pangan yang lebih mudah dan terjangkau bagi masyarakat. Melalui Gerakan Pangan Murah, masyarakat dapat memperoleh berbagai kebutuhan pangan dengan harga yang lebih bersahabat, sekaligus turut mendukung stabilitas pasokan dan harga pangan.<br><br>Pelaksanaan kegiatan di lingkungan TVRI Yogyakarta diharapkan dapat memberikan manfaat secara langsung bagi masyarakat serta menjadi ruang kolaborasi dalam menjaga ketahanan pangan. Berbagai kebutuhan pokok akan tersedia untuk masyakarkat sesuai dengan ketentuan dan ketersediaan untuk masyarakat sesuai dengan ketentuan dan ketersedian selama kegiatan berlangsung.<br><br>Mari manfaatkan kesempatan ini untuk mendapatkan kebutuhan pangan dengan harga terjangkau sekaligus mendukung gerakan bersama dalam mewujudkan ketahanan pangan.<br><br>📍 <strong>Lokasi:</strong> Halaman TVRI Yogyakarta<br>📅 <strong>Tanggal:</strong> 02 September 2026<br>⏰ <strong>Waktu:</strong> 07.30 WIB s/d Selsai<br><br>Gerakan Pangan Murah _ Pangan terjangkau Masyarakat lebih sejahtra.</div>', 'https://www.instagram.com/p/Dcp7Q3Dmu5i/?img_index=1&igsi=MW9qbGcyMDNjN2I1OA==', 'post-images/ELAaqmqgc6JIx8rYUNCT3Vzuss2T1zT3cI69OCCq.jpg', 'Kabar baik untuk masyarakat Yogyakarta \r\nTVRI Yogyakarta akan menjadi bagian dari Gerakan Pangan Murah, menghadirkan berbagai kebutuhan pangan dengan harga yang lebih terjangkau', 'published', '2026-09-01 00:34:00', NULL, NULL, 72, '2026-09-01 00:58:56', '2026-09-08 09:33:49'),
(36, 8, 2, 'Kamis Pon berbusana Tradisional Gagrak Yogyakarta', 'kamis-pon-berbusana-tradisional-gagrak-yogyakarta', '<div>Dalam mewujudkan cinta budaya dan meningkatkan citra organisasi TVRI sebagai Lembaga Penyiaran Publik mewajibkan seluruh Pegawai TVRI Yogyakarta berbusana Tradisional Gagrak Ngayogyakarta</div>', NULL, 'post-images/ekbepN9YTfFGI1uvgzbEm7V2dcOk1XU3GKpELsp9.jpg', 'Dalam mewujudkan cinta budaya dan meningkatkan citra organisasi TVRI sebagai Lembaga Penyiaran Publik mewajibkan seluruh Pegawai TVRI Yogyakarta berbu...', 'published', '2026-08-31 20:30:00', NULL, NULL, 62, '2026-09-01 20:35:30', '2026-09-08 18:34:40'),
(37, 9, 2, 'KAROKE ON TV - KOT LIVE SHOW: KINGDOM OF TALENTS', 'karoke-on-tv-kot-live-show-kingdom-of-talents', '<div>Siap-siap seru-seruan bareng bareng Karoke On TV - KOT Live Show: Kingdom of Talents!<br><br>Jangan lewatkan keseruan dan aksi talenta- talenta pilihan yang akan hadir menemani pemirsa TVRI Yogyakarta. Dipandu oleh host Zhafira &amp; CIndyn, acara ini siap menghadirkan suasana penuh musik, energi, dan hiburan yang panstinya sayang dilewatkan!<br><br>📅 <strong>Jumat, 4 September 2026</strong><br> ⏰ <strong>Pukul 14.30–15.30 WIB</strong><br> 📺 <strong>Live di TVRI Yogyakarta<br></strong><br></div><div><br>Buat kamu yang ingin ikut meramaikan keseruan <strong>KOT Live Show</strong>, bisa berpartisipasi melalui <strong>WA 0851-8311-3339 (Chat/Video Call)</strong>. Siapkan earphone, ruangan yang nyaman, dan jangan lupa ikuti musik serta lirik dari layar handphone! 🎧📱<br><br></div><div><br>Yuk, tunjukkan talenta terbaikmu dan jadikan musik sebagai ruang untuk berekspresi!<br><br></div><div><strong><br>Karaoke On TV – Kingdom of Talents, panggungnya talenta, serunya untuk semua!</strong>&nbsp;<br><br></div><div><br>#KaraokeOnTV #KOTLiveShow #KingdomOfTalents #TVRIYogyakarta #TVRI #Yogyakarta #LiveShow #TalentaYogyakarta #Musik #Hiburan #Zhafira #Cindyn</div>', 'https://www.instagram.com/p/DczqjqKo0Vd/?igsi=bTluZ3lvOTI3ajk2', 'post-images/7sLNDwu6qsRDCyRrWAramEgZCLeCZsVlumAgx5X9.jpg', 'Saatnya unjuk talenta dan seru-seruan bareng Kingdom of Talents!', 'published', '2026-09-04 01:05:00', NULL, NULL, 47, '2026-09-04 01:16:48', '2026-09-08 19:50:13'),
(38, 9, 2, 'RANAH PUBLIK JUM\'AT 04 SEPTEMBER 2026', 'ranah-publik-jumat-04-september-2026-', '<div>RANAH PUBLIK: MEWUJUDKAN LANSIA SEHAT, MANDIRI DAN SEJAHTERA</div><div>Menjadi lanjut usia bukan berarti berhenti berkarya dan beraktivitas. Lansia yang sehat, mandiri, dan sejahtera merupakan bagian penting dalam mewujudkan keluarga dan masyarakat yang berkualitas.</div><div>Melalui program <strong>Ranah Publik</strong> TVRI Yogyakarta, pemirsa diajak melihat lebih dekat berbagai upaya dalam <strong>“Mewujudkan Lansia Sehat, Mandiri dan Sejahtera”</strong>. Pembahasan ini menghadirkan perspektif dari berbagai pihak mengenai pentingnya menjaga kesehatan, meningkatkan kemandirian, serta menciptakan lingkungan yang mendukung kesejahteraan lansia.</div><div>Hadir sebagai narasumber <strong>Drs. Sulistiyo, S.H., C.N., M.Si. – Ketua II Komda Lansia DIY</strong>, <strong>GKBRRAA Paku Alam – Wakil Ketua TP PKK DIY</strong>, <strong>Suyarno, S.Sos., M.A. – Kepala Dinas Sosial DIY</strong>, serta <strong>Dr. dr. Ida I Dewa Putu Pramantara Setiabudi, Sp.PD., K-Ger – Dokter Spesialis Geriatri RS Panti Rapih Yogyakarta</strong>. Diskusi dipandu oleh <strong>Meta Docang</strong> sebagai host.</div><div>📺 <strong>Ranah Publik – Live</strong><br>📅 <strong>Jumat, 4 September 2026</strong><br>⏰ <strong>Pukul 17.00 WIB</strong><br>📍 <strong>TVRI Yogyakarta</strong></div><div>Saksikan Ranah Publik dan temukan berbagai informasi serta inspirasi untuk bersama-sama membangun masa lanjut usia yang <strong>sehat, mandiri, bermartabat, dan sejahtera</strong>.</div><div><strong>TVRI Yogyakarta — Hadir Mengedukasi, Menginspirasi, dan Melayani Masyarakat.</strong></div>', 'https://www.instagram.com/p/Dc0GLULorko/?igsi=czYwNHFqcnhtYmx3', 'post-images/C7NZU2uoAvtRXA9SrYy5yTpxYI7AEVRu4nuo3Gcg.jpg', 'Menjadi lansia bukan berarti berhenti aktif dan berkarya. Yuk, bersama-sama wujudkan masa lanjut usia yang sehat, mandiri, produktif, dan sejahtera!', 'published', '2026-09-04 01:53:00', NULL, NULL, 52, '2026-09-04 01:58:03', '2026-09-08 20:25:26'),
(39, 9, 2, 'LELANG PERALATAN STUDIO DAN PEMANCAR TELEVISI', 'lelang-peralatan-studio-dan-pemancar-televisi-', '<div>Tentu, berikut caption yang cocok untuk <strong>posting Instagram TVRI Yogyakarta</strong> berdasarkan poster tersebut:</div><div>📢 <strong>LELANG PERALATAN STUDIO DAN PEMANCAR TELEVISI</strong> 📺</div><div>TVRI Stasiun D.I. Yogyakarta melalui perantara <strong>Kantor Pelayanan Kekayaan Negara dan Lelang (KPKNL)</strong> akan melaksanakan lelang <strong>peralatan studio dan pemancar televisi</strong> yang berlokasi di <strong>Kabupaten Sleman</strong>.</div><div>Bagi masyarakat yang berminat mengikuti lelang, berikut informasi penting yang perlu diperhatikan:</div><div>📅 <strong>Batas Akhir Penawaran:</strong><br>10 September 2026</div><div>💰 <strong>Batas Akhir Setor Uang Jaminan:</strong><br>9 September 2026</div><div>📍 <strong>Lokasi Objek:</strong> Kabupaten Sleman</div><div>Jangan lewatkan kesempatan untuk mengikuti proses lelang sesuai ketentuan yang berlaku. Pastikan membaca informasi dan persyaratan lelang dengan teliti sebelum melakukan penawaran.</div><div>Untuk informasi lebih lanjut mengenai tata cara dan ketentuan lelang, silakan mengikuti informasi resmi yang tersedia.</div><div><strong>TVRI Yogyakarta — Melayani, Menginspirasi, dan Hadir untuk Negeri.</strong> 🇮🇩</div><div>#TVRIYogyakarta #TVRI #Lelang #LelangTVRI #LelangPeralatan #PeralatanStudio #PemancarTelevisi #KPKNL #Sleman #Yogyakarta #InfoLelang #BanggaMelayaniBangsa #BerAKHLAK</div>', 'https://www.instagram.com/p/DdBNY9eE4Sm/?stkn=bnp4b2t2MTU2ejE2', 'post-images/6gp2HxZr28l7nvsfKmbUCJzNbGngA7kgsWwcMjXH.jpg', 'TVRI Stasiun D.I. Yogyakarta melalui KPKNL membuka kesempatan lelang peralatan studio dan pemancar televisi yang berlokasi di Kabupaten Sleman.', 'published', '2026-09-08 01:14:00', NULL, NULL, 10, '2026-09-08 01:18:18', '2026-09-08 19:19:46');
INSERT INTO `ppids` (`id`, `title`, `description`, `source_link`, `cover_image`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Undang-undang Penyiaran', '<div>&nbsp;Undang-undang utama yang mengatur lembaga penyiaran di Indonesia adalah <strong>Undang-Undang Nomor 32 Tahun 2002 tentang Penyiaran</strong>. UU ini menjadi dasar hukum bagi seluruh kegiatan penyiaran, baik televisi maupun radio, serta mengatur peran lembaga penyiaran publik, swasta, komunitas, dan berlangganan.</div>', 'https://drive.google.com/file/d/1FSQciAYlBnPbWnwKaEfVy0xgp-nSvmW2/view', 'ppid-covers/1765245175_693780f74fb64.jpg', 1, '2025-12-08 11:52:55', '2025-12-08 11:52:55'),
(2, 'Undang-undang keterbukaan informasi', '<div>&nbsp;Undang-undang yang mengatur keterbukaan informasi di Indonesia adalah <strong>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik (KIP)</strong>. UU ini menjamin hak masyarakat untuk memperoleh informasi dari badan publik, sekaligus mengatur kewajiban badan publik dalam menyediakan dan mengumumkan informasi.&nbsp;</div>', 'https://drive.google.com/file/d/1ZMZyRUm6sFo0FXZ5AtXkLoFDp3OI1Gn9/view', 'ppid-covers/1765245240_69378138289d8.jpg', 1, '2025-12-08 11:54:00', '2025-12-08 11:54:00'),
(3, 'Peraturan Pemerintah Nomor 94 Tahun 2021 tentang Disiplin Pegawai Negeri Sipil (PNS)', '<div>Peraturan Pemerintah <strong>Nomor 94 Tahun 2021 tentang Disiplin Pegawai Negeri Sipil (PNS)</strong> mengatur kewajiban, larangan, serta jenis hukuman disiplin bagi PNS. PP ini berlaku sejak <strong>31 Agustus 2021</strong> dan menjadi dasar penegakan disiplin aparatur sipil negara di Indonesia.&nbsp;</div>', 'https://drive.google.com/file/d/1cEJ3Jcjq_Lr1wua5dJw7lh9B3DdmIHIR/view', 'ppid-covers/1765245360_693781b0e8af3.jpg', 1, '2025-12-08 11:56:01', '2025-12-08 11:56:01'),
(4, 'Peraturan Pemerintah Nomor 66 Tahun 2020', '<div>Peraturan Pemerintah <strong>Nomor 66 Tahun 2020</strong> mengatur tentang <strong>Jenis dan Tarif atas Jenis Penerimaan Negara Bukan Pajak (PNBP) yang berlaku pada Lembaga Penyiaran Publik TVRI</strong>. PP ini ditetapkan pada <strong>10 November 2020</strong> dan menjadi dasar hukum bagi TVRI dalam memungut PNBP dari berbagai layanan penyiaran, produksi, hingga pemanfaatan sarana prasarana.&nbsp;</div>', 'https://drive.google.com/file/d/1yH3Sl5CaoamnzrV-qpbDluxohTYBI2tX/view', 'ppid-covers/1765245467_6937821b9cd32.jpg', 1, '2025-12-08 11:57:47', '2025-12-08 11:57:47'),
(5, 'Laporan LKJIP 2026', '<div>&nbsp;LKJIP TVRI Yogyakarta Tahun 2026 Semester I : adalah laporan kinerja resmi stasiun TVRI D.I. Yogyakarta yang disusun sebagai bentuk transparansi dan akuntabilitas</div>', 'https://drive.google.com/file/d/1DxSmQw3l9oj0vNtQssx0DPhwRJxqrkSh/view?usp=sharing', 'ppid-covers/ppid-RQm2H1V0nGMLxpQ6Pd6z.jpg', 1, '2026-09-01 01:49:13', '2026-09-01 01:51:57');
INSERT INTO `reformasi_rbs` (`id`, `title`, `slug`, `description`, `file_link`, `cover_image`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'LAKIP/LKJIP TVRI Yogyakarta Tahun 2023', 'lakiplkjip-tvri-yogyakarta-tahun-2023-N2Sz5', '<div><strong>LAKIP/LKJIP TVRI Yogyakarta Tahun 2023</strong> adalah laporan kinerja resmi stasiun TVRI D.I. Yogyakarta yang disusun sebagai bentuk transparansi dan akuntabilitas publik sesuai amanat <strong>Perpres No. 29 Tahun 2014</strong> tentang Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP). Laporan ini memuat capaian program, sasaran strategis, serta evaluasi kinerja TVRI Yogyakarta sepanjang tahun 2023.&nbsp;</div>', 'https://drive.google.com/file/d/1z_X1l4wS6O4Tagb_lFjUbeQRelkRgJGj/view', 'reformasi-covers/lqqwhoCzN1pxvPdUM9QvUHBVLfB28j0HDipfFV9Q.jpg', 1, '2025-12-08 12:00:08', '2025-12-08 12:00:08'),
(2, 'Rencana Strategis (Renstra) Tahun 2020-2024', 'rencana-strategis-renstra-tahun-2020-2024-mAI7g', '<div>Rencana Strategis (Renstra) Tahun 2020-2024 TVRI Stasiun Yogyakarta merupakan panduan kegiatan pelaksanaan penyiaran di TVRI Stasiun Yogyakarta yang mengacu pada Renstra 2020-2024 LPP TVRI dalam rangka implementasi Renstra TVRI nasional pada tingkat TVRI daerah.</div>', 'https://drive.google.com/file/d/1-CfCPghXZAW0RlvRnQlog8vamd1r-kZC/view', 'reformasi-covers/eTZcLMX52iRXaU3pItwnBdcqmr72vrsS3gjbTYI7.jpg', 1, '2025-12-08 12:02:14', '2025-12-08 12:02:14'),
(3, 'Survey Kepuasan Masyarakat', 'survey-kepuasan-masyarakat-MvbQi', '<div>Hasil Survey Kepuasan Masyarakat terhadap Layanan TVRI Yogyakarta</div>', 'https://docs.google.com/spreadsheets/d/1bxGOH3bKcuxZu-XsG0usIYSq7qMkYXiH/edit?usp=sharing&ouid=116714311782006542608&rtpof=true&sd=true', 'reformasi-covers/Z64Q4IMCsmiuNkYKd9urSaMpPFe5yX7vbLNye0cd.png', 1, '2026-07-02 19:59:50', '2026-07-02 20:00:06'),
(4, 'Survey Kepuasan Pemirsa', 'survey-kepuasan-pemirsa-fblXH', '<div>Hasil Survey Kepuasan Pemirsa TVRI Yogyakarta terhadap semua Program acara TVRI</div>', 'https://docs.google.com/spreadsheets/d/1M-y2DXi2DzuWeG1ao2V9RUzCFH0_r91e/edit?usp=sharing&ouid=116714311782006542608&rtpof=true&sd=true', 'reformasi-covers/vSIBa3QQEJUl5dc1xkXBNg5mvOlgX4yrNdiWLMPA.png', 1, '2026-07-02 20:02:18', '2026-07-02 20:02:18'),
(5, 'Sosialisasi Pembangunan Zona Integritas Menuju WBK WBBM', 'sosialisasi-pembangunan-zona-integritas-menuju-wbk-wbbm-CfoBI', '<div>&nbsp;</div><div><em>Menuju Zona Integritas Wilayah Bebas Korupsi (WBK) dan Wilayah Birokrasi Bersih dan Melayani (WBBM)</em> TVRI Stasiun D.I Yogyakarta.&nbsp;</div>', 'https://drive.google.com/drive/folders/1pyjO123J3jQ22G2uMGN5rKtrD-J4thGi?usp=sharing', 'reformasi-covers/garV6y89QJ37hw3racvgX6PjsIvbqrD9k0tM0uUk.png', 1, '2026-07-02 20:25:10', '2026-07-02 20:42:59'),
(6, 'NOTA DINAS PENYAMPAIAN LAPORAN FKP 2026', 'nota-dinas-penyampaian-laporan-fkp-2026-4TABe', '<div>Forum Konsultasi Publik dilaksanakan dalam Rangka memberikan Ruang bagi Publik dalam memberikan Masukan terhadap Pelayanan di TVRI Yogyakarta</div>', 'https://drive.google.com/file/d/1ywxq3rhMDwkTXaPwZpiX6ajhJtumUqXj/view?usp=sharing', 'reformasi-covers/BFp7OOYrsd3iS7xljWyjCs1qkSG2jsxosQ9o4Bio.png', 1, '2026-07-02 22:16:35', '2026-07-02 22:16:35'),
(7, 'Laporan PEKPPP Mandiri TVRI Yogyakarta', 'laporan-pekppp-mandiri-tvri-yogyakarta-ANouW', '<div>&nbsp;Pelayanan publik merupakan pelayanan dasar penyelenggaraan pemerintah. Pelayanan publik sebagai indikator penting dalam penilaian kinerja pemerintah, baik di tingkat pusat maupun daerah. Pelayanan publik pada hakekatnya adalah amanah yang tertera dalam Undang-Undang Nomor 25 Tahun 2009 tentang Pelayanan Publik dalam Pasal 1 ayat (1) yang menyatakan pelayanan publik adalah kegiatan dalam rangka pemenuhan kebutuhan pelayanan sesuai dengan peraturan perundang-undangan bagi setiap warga negara dan penduduk atas barang, jasa atau pelayanan administratif yang disediakan oleh penyelenggara publik.&nbsp;</div>', 'https://drive.google.com/file/d/1RoUtOkmVxhSkEYL-vWIfwXCzLwU2zOZH/view?usp=sharing', 'reformasi-covers/Z8C0oyEWiGbhfj5EwrbbogFX5ZaOU3UmxEFpPbZ8.png', 1, '2026-07-02 22:23:17', '2026-07-02 22:23:17'),
(8, 'Dokumentasi Sosialisasi Zona Integritas WBK WBBM', 'dokumentasi-sosialisasi-zona-integritas-wbk-wbbm-BrQRv', '<div>TVRI Yogyakarta menuju Zona Integritas WBK dan WBBM sebagai Lembaga Penyiaran Publik</div>', 'https://drive.google.com/file/d/1ngSimxJVUaBty4cw8GlPxt-R_NMF6WbQ/view?usp=sharing', 'reformasi-covers/Z7uHD43EQq62cnpZNyvRiJB3kwoLOQs12CMxIeHO.jpg', 1, '2026-07-02 22:39:51', '2026-07-02 22:41:06'),
(9, 'Informasi Maklumat Pelayanan TVRI Stasiun Yogyakarta', 'informasi-maklumat-pelayanan-tvri-stasiun-yogyakarta-4W8RL', '<div>TVRI Stasiun Yogyakarta berkomitmen memberikan pelayanan yang profesional, transparan, akuntabel, serta berorientasi pada kepuasan masyarakat. Kami senantiasa menghadirkan layanan publik yang berkualitas dengan menjunjung tinggi integritas, responsivitas, dan pelayanan prima.&nbsp;<br>Bersama TVRI, wujudkan pelayanan yang terpercaya untuk masyarakat</div>', 'https://www.instagram.com/p/Dbj1VzPk0H3/?igsh=MTdod3Zla281YTBxaQ==', 'reformasi-covers/aK0NqeCa3CezzIITgEAg3IVnlmK8VhTDyAUMpqxG.jpg', 1, '2026-08-02 13:43:57', '2026-08-02 13:43:57'),
(10, 'Hasil Survei Kepuasan Masyarakat TVRI stasiun Yogyakarta', 'hasil-survei-kepuasan-masyarakat-tvri-stasiun-yogyakarta-kkQat', '<div>Hasil Survei Kepuasan Masyarakat TVRI Stasiun Yogyakarta Semester 1 (Januari-Juni 2026). Menunjukkan bahwa secara keseluruhan TVRI Stasiun Yogyakarta Meraih nilai Indeks Kepuasan Masyarakat sebesar 91.75 dengan predikat A (Sangat Baik).<br><br>Trima Kasih atas kepepercayaan dan pastisipasi masyarakat.&nbsp;<br><br>Hasil Survei Kepuasan Masyarakat menjadi cerminan sekaligus motivasi bagi TVRI Stasiun yogyakarta untuk terus menigkatkan kualitas layanan publik, menyajikan infromasi yang akurat, edukatif serta menghadirkan tayangan yang mencerdaskan dan melestarikan nilai-nilai budaya.&nbsp;<br><br>Masukan dan apresiasi dari masyarakat menjadi bagian penting dalam langkah kami untuk terus berbenah dan memberikan pelayanan penyiaran publik yang semakin berkualitas.<br><br>TVRI Yogyakarta Media Pemersatu Bangsa&nbsp;<br><br></div>', 'https://www.instagram.com/p/DbkdeKikxk_/?igsh=MW1ub3R5Y2dpamMwZw==', 'reformasi-covers/SRrVFlgytxhGycIIIAEMy5ic2psUUEQYnYBP632v.jpg', 1, '2026-08-03 13:48:54', '2026-08-03 13:48:54');
