INSERT INTO `tugas_fungsis` (`id`, `type`, `order`, `image`, `content`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'tugas', 1, 'task-images/tf-HAGrCvcizFXqcRpUI5wR.jpg', '<div>TVRI Stasiun Yogyakarta merupakan bagian dari lembaga Penyiaran Publik Televisi Republik Indonesia (TVRI) yang memiliki tugas menyelenggarakan kegiatan pemyiaran televisi publik di wilayah Daerah Istimewa Yogyakarta.<br><br>Dalam menjalankan tugasnya, TVRI Stasiun Yogyakarta berperan dalam menyediakan informasi, pendidikan, hiburan yang sehat, serta layanan publik melalui program siaran yang berkualitas, berimbang, edukatif, dan mecerminkan nilai-nilai budaya serta kearifan lokal Yogyakarta.<br><br>Tugas Utama TVRI Stasiun yogyakarta</div><ol><li><strong>Menyelenggarakan penyiaran publik </strong>yang memberikan infromasi yang akurat, edukatif, dan bermanfaat bagi masyarakat.</li><li><strong>Menyediakan program pendidikan dan infromasi</strong> yang mendukung peningkatan pengetahuan, wawasan, serta kualitas kehidupan masyarakat.</li><li><strong>Mengangkat dan melestarikan budaya loka</strong>l Daerah istimewa Yogyakarta melalui program-program yang memperkenalkan seni, tradisi,bahsa, sejarah, dan kearifan lokal.</li><li><strong>Memberikan ruang bagi masyarakat</strong> untuk menyampaikan aspirasi, informasi, serta berbagi potensi dan kegiatan yang berkembang di wilayah Yogyakata.</li><li><strong>Mendukung pembagunan daerah</strong> melalui penyebarluasan infromasi mengenai kebijakan, program pemerintah, pelayanan publik, serta berbagi capaian pembagunan.</li><li><strong>Menyajikan hiburan yang sehat dan berkualitas</strong> dengan tetap memperhatikan nilai edukasi, budaya, norma, serta kepentingan masyarakat.</li><li><strong>Mengembangkan konten digital dan multiplatfrom</strong> sebagai upaya memperluas jangkauan informasi dan layanan publik TVRI kepada masyarakat di era digital.</li><li><strong>Membangun kemitraan dengan berbagai pihak</strong>, baik pemerintah, lembaga pendidikan, komunitas, pelaku usaha, maupun masyarakat dalam mendukung penyelenggaraan penyiaran publik.</li></ol>', 1, '2025-12-08 12:13:15', '2026-08-11 01:04:01'),
(2, 'fungsi', 2, 'task-images/tf-bnfED9wN10MIN9bAmAJq.jpg', '<div>Fungsi Stasiun D.I. Yogyakarta merupak bagian dari Lembaga Penyiaran Publik Televisi Republik Indonesia yang memiliki peran strategis dalm memberikan pelayanan informasi, pendidikan, hiburan, yang sehat, serta menjadi perekat sosial bagi masyarakat.<br><br>Dalam menjalankan tugasnya sebagai lembaga penyiaran publik, TVRI Stasiun D.I. Yogyakarta memiliki fungsi sebagai berikut:<br><br></div><ol><li><strong>Pelayanan Informasi Publik</strong><br>Menyajikan informasi yang aktual, akurat, berimbang , dan terpercaya mengenai berbagi pristiwa serta perkembangan di Daerah Istimewa Yogyakarta dan sekitarnya.</li><li><strong>Pendidikan dan Pencerdasan Masyarakat </strong><br>Menghadirkan program-program edukatif yang memberikan pengetahuan, wawasan, dan informasi, yang bermanfaat bagi masyarakat dari berbagai kalangan&nbsp;</li><li><strong>Penyedian Hiburan yang Sehat</strong><br>Menyajikan tayangan hiburan yang berkualitas, positif, dan sesuai dengan nilai-nilai budaya serta norma yang berlaku di masyarakat</li><li><strong>Pelestarian dan Pengembangan Budaya</strong><br>Menjadi ruang bagi pelestarian, pengenalan, dan pengembangan seni serta budaya Yogyakarta dan budaya Nusantara melalui berbagai program siaran.</li><li><strong>Perekat Sosial dan Pemersatu Masyarakat</strong><br>Mendorong terciptanya kebersamaan, toleransi, persatuan, dan kesatuan melalui konten yang mencerminkan keberagaman masyarakat serta nilai-nilai kebangsaan.</li><li><strong>Kontrol Sosial</strong><br>Menjadi media yang memberikan ruang bagi masyarakat untuk memperoleh informasi, menyampaikan aspirasi, serta mengikuti perkembangan kebijakan dan dinamika sosial di lingkungan masyarakat</li><li><strong>Pengembangan Penyiaran dan Teknologi Media </strong><br>Mengembangkan kualitas produksi dan penyiaran melalui pemanfaatan teknologi serta berbagai platfrom media digital agar informasi dan konten TVRI dapat menjangkau masyarakat secara lebih luas.</li><li><strong>Pelayanan dan Keterbukaan Informasi Publik</strong><br>Memberikan pelayanan infromasi kepada masyarakat secara transparan, akuntabel, efektif, dan sesuai dengan ketentuan peraturan perundang-undangan.</li><li><strong>Penegembangan Sumber Daya Manusia</strong><br>Mendukung peningkata kompetensi dan profesionalisme sumber daya manusia di bidang penyiaran, jurnalistik, produksi, media digital. administrasi, dan bidang pendukung lainnya.</li></ol><div><br></div>', 1, '2025-12-08 12:13:38', '2026-08-09 18:17:13');
